pageStyle:
.col-md-12.page-description-content {
    padding: 50px 60px;
    background-image: url(https://hugeampkpncms.org/sites/default/files/images/kp4cd/kpn_website_bg.png);
    background-size: 1550px 300px;
    background-position: -130px 60px;
    background-repeat: no-repeat;
}

#home_page_title {
font-family: 'Barlow Condensed';
font-style: normal;
font-weight: 500;
font-size: 82.8468px;
line-height: 90%;
/* or 75px */
letter-spacing: -0.05em;
color: #185468;
mix-blend-mode: normal;
}

#home_page_tagline {
    font-family: 'Inter';
    font-style: normal;
    font-weight: 400;
    font-size: 22px;
    line-height: 150%;
    letter-spacing: -0.019em;
    color: #083A4B;
    margin-top: 20px;
    padding-left: 3px;
}

.kp-tabs-contents {
    border: none;
}

.section-header {
    display: none;
}

#section_wrapper_section_1 {
    background: linear-gradient(180deg, rgba(143, 226, 255, 1) 0%, rgba(255, 255, 255, 1) 100%);
    width: calc(100% + 40px);
    margin-left: -20px;
}

#section_wrapper_section_1 .page-description-content {
    background: none !important;
padding: 0;
}

.white-crescent {
    width: 100%;
    margin-top: -1.6%;
}

#category_icons {
    max-width: 960px; 
    margin:auto;
}

#category_icons .icon{
    width: 20%;
    display: inline-block;
text-align: center;
}

#category_icons .icon img{
width: 150px;
}

#category_icons .icon .name{
display: block;
    color: #185468 !important;
font-family: 'Barlow Condensed';
font-style: normal;
font-weight: 600;
font-size: 20px;
line-height: 31px;
}

.interested-in {
font-family: 'Barlow Condensed';
font-style: normal;
font-weight: 500;
font-size: 26px;
line-height: 146%;
text-align: center;
letter-spacing: -0.019em;
color: #60B8ED;
display: block;
    margin-top: -80px;
    margin-bottom: 80px;
}


.bottom-section-contents {
    max-width: 960px; 
    margin:auto;
}

.bottom-content {
    width: calc(50% - 50px);
    display: inline-block;
    position: relative;
    vertical-align: top;
}

.bottom-content.left {
    Margin-right: 50px;
}

.bottom-content.right {
    Margin-left: 50px;
}

#section_section_2 .page-description-content {
background: none;
}

.header-wrapper {
height: auto;
border-bottom: 2px solid #255D71;
    margin-bottom: 25px;
}

.header-wrapper .title {
font-family: 'Barlow Condensed';
font-style: normal;
font-weight: 500;
font-size: 30px;
line-height: 36px;
letter-spacing: -0.05em;
color: #185468;
}

.header-wrapper a {
color: #fff !important;
position: absolute;
right: 0;
padding: 5px 10px;
width: auto;
height: 26px;
background: #185468;
border-radius: 5px;
}

.news, .events {
    margin-top: 20px;
clear: both;
}

.news.big-news img {
    width: 100%;
}

.news.small-news img  {
    width: 150px;
    float: left;
    margin-right: 15px;
margin-bottom: 20px;
}

.event img  {
    width: 120px;
    float: left;
    margin-right: 15px;
}

.text-block h4 {
    font-style: normal;
    font-weight: 500;
    font-size: 20px;
    line-height: 23px;
    position: relative;
}

.events-btn {
    align-items: center;
    padding: 0px 5px 3px 5px;
    margin: 0 auto;
    width: auto;
    height: 20px;
    background: #cccccc;
    font-size: 13px;
    border-radius: 5px;
    position: absolute;
    display: block;
    top: 0;
    right: 0;
    color: #000000 !important;
}

.events-btn.upcoming {
    background: #8FE2FF;
}
